PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY,google_sub TEXT UNIQUE NOT NULL,handle TEXT UNIQUE NOT NULL,bio TEXT NOT NULL DEFAULT '',favorite TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS oauth_states(state TEXT PRIMARY KEY,browser TEXT NOT NULL,verifier TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS topics(id TEXT PRIMARY KEY,author TEXT NOT NULL REFERENCES members(id),category TEXT NOT NULL,title TEXT NOT NULL,movie TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL,locked INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS topics_created ON topics(created DESC);
CREATE TABLE IF NOT EXISTS posts(id TEXT PRIMARY KEY,topic TEXT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,author TEXT NOT NULL REFERENCES members(id),body TEXT NOT NULL,spoiler INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS posts_topic ON posts(topic,created);
CREATE TABLE IF NOT EXISTS reviews(member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE,movie TEXT NOT NULL,rating INTEGER NOT NULL,body TEXT NOT NULL,spoiler INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,PRIMARY KEY(member,movie));
CREATE TABLE IF NOT EXISTS shelves(member TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE,movie TEXT NOT NULL,PRIMARY KEY(member,movie));
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,author TEXT NOT NULL REFERENCES members(id),post TEXT NOT NULL REFERENCES posts(id),reason TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS write_limits(member TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
